DECLARE @Counter INT = 1;
WHILE @Counter <= 5
BEGIN
    PRINT 'Iteration: ' + CAST(@Counter AS VARCHAR(10));
    SET @Counter = @Counter + 1;
END

WHILE @Counter <= 100
BEGIN
    IF @Counter = 5
        BREAK;
    PRINT 'Counter: ' + CAST(@Counter AS VARCHAR(10));
    SET @Counter = @Counter + 1;
END

WHILE @Counter < 10
BEGIN
    SET @Counter = @Counter + 1;
    IF @Counter % 2 = 0
        CONTINUE;
    PRINT 'Odd number: ' + CAST(@Counter AS VARCHAR(10));
END
